package com.gameaggregator.incidentservice.api;import jakarta.validation.constraints.*;import java.util.*;import java.util.UUID;public final class IncidentDtos{private IncidentDtos(){}public record Create(@NotBlank String incidentNumber,@NotBlank String title,@NotBlank String description,@Pattern(regexp="SEV1|SEV2|SEV3|SEV4")String severity,UUID assigneeId,UUID relatedDeploymentId,@NotEmpty Set<String> affectedServices,@NotNull UUID actorId){}public record Actor(@NotNull UUID actorId,String message){}public record Assign(@NotNull UUID actorId,@NotNull UUID assigneeId){}public record Postmortem(@NotNull UUID actorId,@NotBlank String content){}public record Timeline(@NotNull UUID actorId,@NotBlank String type,@NotBlank String message){}}